  { \True $3\,\text{m}$ }
  { $4\,\text{m}$ }
  { $2{,}5\,\text{m}$ }
}{
\begin{tikzpicture}[>=stealth, scale=0.45, font=\scriptsize]
\fill[gray!35] (-5.5, -1.1) rectangle (5.5, 0);
