\draw[<->] (-4, -0.6) -- (4, -0.6) node[midway, fill=gray!35, inner sep=1pt] {$8\,\text{m}$};
\draw[dashed, gray] (0, 4) -- (4.75, 4);
\draw[<->, blue!70!black] (4.65, 0) -- (4.65, 4) node[midway, right, inner sep=1.5pt] {$4\,\text{m}$};
\draw[<->, white, thick] (-2, 1.5) -- (2, 1.5) node[midway, fill=red!65!black, inner sep=1pt] {$4\,\text{m}$};
\end{tikzpicture}
}
\loigiai{
\begin{center}
\begin{tikzpicture}[>=stealth, line cap=round, line join=round, scale=0.72, font=\scriptsize]
\draw[->] (-2.8,0) -- (2.9,0) node[below] {$x$};
\draw[->] (0,-0.55) -- (0,2.3) node[left] {$y$};
\draw[thick, red!80!black, smooth, domain=-2.35:2.35] plot (\x, {1.8 - (1.8/4.84)*(\x)^2});
\draw[thick] (-2.2,0.0) -- (2.2,0.0);
\draw[thick, blue!75!black] (1.1,0.0) -- (1.1,1.35);
\draw[dashed, gray] (2.2,0) -- (2.2,0.0);
